29	template <typename T>
30	std::unique_ptr<TilingBaseClass> TILING_CLASS(gert::TilingContext* context)
31	{
32	    return std::unique_ptr<T>(new (std::nothrow) T(context));
33	}
34	
35	using TilingClassCase = std::unique_ptr<TilingBaseClass> (*)(gert::TilingContext*);
36	
37	// Helper: 遍历 tiling cases 并尝试执行，若任一 case 返回非 GRAPH_PARAM_INVALID 的状态则返回该状态。
38	// 若无可用 template 则返回 ge::GRAPH_FAILED。
39	inline ge::graphStatus RunTilingCasesHelper(const std::map<int32_t, TilingClassCase>& tiling_cases,
40	                                            gert::TilingContext* context)
41	{
42	    for (auto it = tiling_cases.begin(); it != tiling_cases.end(); ++it) {
43	        auto tilingTemplate = it->second(context);
44	        if (tilingTemplate != nullptr) {
45	            ge::graphStatus status = tilingTemplate->DoTiling();
46	            if (status != ge::GRAPH_PARAM_INVALID) {
47	                OP_LOGD(context, "Do general op tiling success priority=%d", it->first);
48	                return status;
49	            }
50	            OP_LOGD(context, "Ignore general op tiling priority=%d", it->first);
51	        }
52	    }
53	    return ge::GRAPH_FAILED;
54	}
55	
56	class TilingCases {
57	public:
58	    explicit TilingCases(std::string op_type) : op_type_(std::move(op_type)) {}
59	
60	    template <typename T>
61	    void AddTiling(int32_t priority)
62	    {
63	        OP_CHECK_IF(cases_.find(priority) != cases_.end(), OP_LOGE(op_type_, "There are duplicate registrations."),
64	                    return);
65	        cases_[priority] = TILING_CLASS<T>;
66	        OP_CHECK_IF(cases_[priority] == nullptr,
67	                    OP_LOGE(op_type_, "Register op tiling func failed, please check the class name."), return);
68	    }
69	
70	    const std::map<int32_t, TilingClassCase>& GetTilingCases() { return cases_; }
71	
72	private:
73	    std::map<int32_t, TilingClassCase> cases_;
74	    const std::string op_type_;
75	};
76	
77	// --------------------------------Interfacce with soc version --------------------------------
78	class TilingRegistryNew {
79	public:
80	    TilingRegistryNew() = default;
81	
82	#ifdef ASCENDC_OP_TEST
83	    static TilingRegistryNew& GetInstance();
84	#else
85	    static TilingRegistryNew& GetInstance()
86	    {
87	        static TilingRegistryNew registry_impl_;
88	        return registry_impl_;
89	    }
90	#endif
91	
92	    std::shared_ptr<TilingCases> RegisterOp(const std::string& op_type, int32_t soc_version)
93	    {
94	        auto soc_iter = registry_map_.find(soc_version);
95	        if (soc_iter == registry_map_.end()) {
96	            std::map<std::string, std::shared_ptr<TilingCases>> op_type_map;
97	            op_type_map[op_type] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(op_type));
98	            registry_map_[soc_version] = op_type_map;
99	        } else {
100	            if (soc_iter->second.find(op_type) == soc_iter->second.end()) {
101	                soc_iter->second[op_type] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(op_type));
102	            }
103	        }
104	
105	        OP_CHECK_IF(registry_map_[soc_version][op_type] == nullptr,
106	                    OP_LOGE(op_type, "Register tiling func failed, please check the class name."), return nullptr);
107	        return registry_map_[soc_version][op_type];
108	    }
109	
110	    ge::graphStatus DoTilingImpl(gert::TilingContext* context)
111	    {
112	        int32_t soc_version;
113	        const char* op_type = context->GetNodeType();
114	        if (!GetSocVersionFromContext(context, soc_version, op_type, /*require_valid*/ true)) {
115	            return ge::GRAPH_FAILED;
116	        }
117	        auto tilingTemplateRegistryMap = GetTilingTemplates(op_type, soc_version);
118	        ge::graphStatus status = RunTilingCasesHelper(tilingTemplateRegistryMap, context);
119	        if (status == ge::GRAPH_FAILED) {
120	            OP_LOGE(op_type, "Do op tiling failed, no valid template is found.");
121	        }
122	        return status;
123	    }
124	
125	    ge::graphStatus DoTilingImpl(gert::TilingContext* context, const std::vector<int32_t>& priorities)
126	    {
127	        int32_t soc_version;
128	        const char* op_type = context->GetNodeType();
129	        if (!GetSocVersionFromContext(context, soc_version, op_type, /*require_valid*/ false)) {
130	            return ge::GRAPH_FAILED;
131	        }
132	
133	        auto tilingTemplateRegistryMap = GetTilingTemplates(op_type, soc_version);
134	        for (auto priority_id : priorities) {
135	            auto tilingCaseIter = tilingTemplateRegistryMap.find(priority_id);
136	            if (tilingCaseIter != tilingTemplateRegistryMap.end()) {
137	                auto templateFunc = tilingCaseIter->second(context);
138	                if (templateFunc != nullptr) {
139	                    ge::graphStatus status = templateFunc->DoTiling();
140	                    if (status == ge::GRAPH_SUCCESS) {
141	                        OP_LOGD(context, "Do general op tiling success priority=%d", priority_id);
142	                        return status;
143	                    }
144	                    OP_LOGD(context, "Ignore general op tiling priority=%d", priority_id);
145	                }
146	            }
147	        }
148	        return ge::GRAPH_FAILED;
149	    }
150	
151	    const std::map<int32_t, TilingClassCase>& GetTilingTemplates(const std::string& op_type, int32_t soc_version)
152	    {
153	        auto soc_iter = registry_map_.find(soc_version);
154	        OP_CHECK_IF(soc_iter == registry_map_.end(),
155	                    OP_LOGE(op_type, "Get op tiling func failed, please check the soc version %d", soc_version),
156	                    return empty_tiling_case_);
157	        auto op_iter = soc_iter->second.find(op_type);
158	        OP_CHECK_IF(op_iter == soc_iter->second.end(),
159	                    OP_LOGE(op_type, "Get op tiling func failed, please check the op name."),
160	                    return empty_tiling_case_);
161	        return op_iter->second->GetTilingCases();
162	    }
163	
164	private:
165	    // 从 context 中提取 soc version 的通用逻辑，减少重复代码。
166	    // 返回 true 表示成功获取；返回 false 表示发生错误（例如 compileInfo 为空或需要有效 soc 但无法获取）。
167	    bool GetSocVersionFromContext(gert::TilingContext* context, int32_t& soc_version, const char* op_type,
168	                                  bool require_valid)
169	    {
170	        soc_version = (int32_t)platform_ascendc::SocVersion::RESERVED_VERSION;
171	        auto platformInfoPtr = context->GetPlatformInfo();
172	        if (platformInfoPtr == nullptr) {
173	            auto compileInfoPtr = reinterpret_cast<const CompileInfoCommon*>(context->GetCompileInfo());
174	            OP_CHECK_IF(compileInfoPtr == nullptr, OP_LOGE(op_type, "compileInfoPtr is null."), return false);
175	            soc_version = compileInfoPtr->socVersion;
176	            OP_LOGD(context, "soc version in compileInfo is %d", soc_version);
177	        } else {
178	            auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
179	            soc_version = static_cast<int32_t>(ascendcPlatform.GetSocVersion());
180	            OP_LOGD(context, "soc version is %d", soc_version);
181	            if (require_valid && soc_version == (int32_t)platform_ascendc::SocVersion::RESERVED_VERSION) {
182	                OP_LOGE(op_type, "Do op tiling failed, cannot find soc version.");
183	                return false;
184	            }
185	        }
186	        return true;
187	    }
188	
189	    std::map<int32_t, std::map<std::string, std::shared_ptr<TilingCases>>> registry_map_; // key is socversion
190	    const std::map<int32_t, TilingClassCase> empty_tiling_case_{};
191	};
