207	    template <typename T>
208	    RegisterNew& tiling(int32_t priority, const std::vector<int32_t>& soc_versions)
209	    {
210	        for (int32_t soc_version : soc_versions) {
211	            auto tilingCases = TilingRegistryNew::GetInstance().RegisterOp(op_type_, soc_version);
212	            OP_CHECK_IF(tilingCases == nullptr, OP_LOGE(op_type_, "Register op tiling failed, please the op name."),
213	                        return *this);
214	            tilingCases->AddTiling<T>(priority);
215	        }
216	        return *this;
217	    }
218	
219	private:
220	    const std::string op_type_;
221	};
