291	        if (halfPixelCenters_ != ATTR_HALF_PIXEL_CENTERS_IDX) {
292	            return true;
293	        } else {
294	            // 整数倍缩小，且倍数为奇数
295	            if (FloorScaleH % EVEN_FACTOR == 1 && FloorScaleW % EVEN_FACTOR == 1) {
296	                return true;
297	            }
298	            return false;
299	        }
300	    }
301	}
