303	bool ResizeBilinearV2AscendCTilingImpl::IsMatchBroadCastNCHW()
304	{
305	    if (dtypeX_ != dtypeY_) {
306	        return false;
307	    }
308	
309	    if (format_ != ge::FORMAT_NCHW) {
310	        return false;
311	    }
312	
313	    if (lenDesH_ * lenDesW_ * dtypeSizeY_ < MIN_C_SIZE) {
314	        return false;
315	    }
316	
317	    return (lenSrcH_ == 1 && lenSrcW_ == 1);
318	}
