326	    if (lenC_ * dtypeSizeX_ < MIN_C_SIZE) {
327	        return false;
328	    }
329	
330	    if (format_ != ge::FORMAT_NHWC) {
331	        return false;
332	    }
333	
334	    return (lenSrcH_ == 1 && lenSrcW_ == 1);
335	}
