354	void ResizeBilinearV2AscendCTilingImpl::DoTilingAllCopy()
355	{
356	    realCoreNum_ = (yShape_.GetShapeSize() < coreNum_) ? yShape_.GetShapeSize() : coreNum_;
357	    splitBlockFactor_ = Ops::Base::FloorDiv(yShape_.GetShapeSize(), realCoreNum_);
358	    splitBlockTailFactor_ = yShape_.GetShapeSize() - splitBlockFactor_ * realCoreNum_;
359	    ubCFactor_ = ubBlockNum_ / DB_BUFF_NUM * ONE_BLOCK_SIZE / dtypeSizeX_;
360	}
361	
362	void ResizeBilinearV2AscendCTilingImpl::DoTilingPointCopy()
363	{
364	    // N H多核双切分
365	    int64_t np = FindBest2DTiling(lenN_, lenDesH_);
366	    nFactor_ = Ops::Base::CeilDiv(lenN_, np);
367	
368	    int64_t hp = coreNum_ / np;
369	    hFactor_ = Ops::Base::CeilDiv(lenDesH_, hp);
370	
371	    realCoreNum_ = Ops::Base::CeilDiv(lenN_, nFactor_) * Ops::Base::CeilDiv(lenDesH_, hFactor_);
372	    if (realCoreNum_ <= coreNum_ / EVEN_FACTOR) {
373	        wFactor_ = Ops::Base::CeilDiv(lenDesW_, coreNum_ / realCoreNum_);
374	        realCoreNum_ *= Ops::Base::CeilDiv(lenDesW_, wFactor_);
375	    }
376	
377	    if (realCoreNum_ <= coreNum_ / EVEN_FACTOR) {
378	        cFactor_ = Ops::Base::CeilDiv(lenC_, coreNum_ / realCoreNum_);
379	        realCoreNum_ *= Ops::Base::CeilDiv(lenC_, cFactor_);
380	    }
381	
382	    realCoreNum_ = Min(realCoreNum_, coreNum_);
383	
384	    // UB切分
385	    int64_t wcLenAlign = Ops::Base::CeilAlign(wFactor_ * cFactor_, ONE_BLOCK_SIZE / dtypeSizeX_);
386	    int64_t vol4AxisC = (ubBlockNum_ / DB_BUFF_NUM) * ONE_BLOCK_SIZE / dtypeSizeX_;
387	    if (vol4AxisC < cFactor_) {
388	        ubNFactor_ = 1;
389	        ubHFactor_ = 1;
390	        ubWFactor_ = 1;
391	        ubCFactor_ = vol4AxisC;
392	    } else if (vol4AxisC < wcLenAlign) {
393	        ubNFactor_ = 1;
394	        ubHFactor_ = 1;
395	        ubWFactor_ = vol4AxisC / cFactor_;
396	        ubCFactor_ = cFactor_;
397	    } else if (vol4AxisC < hFactor_ * wcLenAlign) {
398	        ubNFactor_ = 1;
399	        ubHFactor_ = vol4AxisC / (wcLenAlign);
400	        ubWFactor_ = wFactor_;
401	        ubCFactor_ = cFactor_;
402	    } else {
403	        ubNFactor_ = vol4AxisC / (hFactor_ * wcLenAlign);
404	        ubHFactor_ = hFactor_;
405	        ubWFactor_ = wFactor_;
406	        ubCFactor_ = cFactor_;
407	    }
408	}
409	
410	void ResizeBilinearV2AscendCTilingImpl::DoTilingBroadCastNCHW()
411	{
412	    // HW合轴 N->C->HW依次分核
413	    int64_t lenHW = lenDesH_ * lenDesW_;
414	    if (lenN_ * lenC_ <= coreNum_) {
415	        int64_t tileNum = coreNum_ / (lenN_ * lenC_);
416	        nFactor_ = 1;
417	        cFactor_ = 1;
418	        hwFactor_ = Ops::Base::CeilDiv(lenHW, tileNum);
419	        realCoreNum_ = lenN_ * lenC_ * Ops::Base::CeilDiv(lenHW, hwFactor_);
420	    } else if (lenN_ <= coreNum_) {
421	        int64_t tileNum = coreNum_ / lenN_;
422	        nFactor_ = 1;
423	        cFactor_ = Ops::Base::CeilDiv(lenC_, tileNum);
424	        realCoreNum_ = lenN_ * Ops::Base::CeilDiv(lenC_, cFactor_);
425	    } else {
426	        nFactor_ = Ops::Base::CeilDiv(lenN_, coreNum_);
427	        realCoreNum_ = Ops::Base::CeilDiv(lenN_, nFactor_);
428	    }
429	    realCoreNum_ = Min(realCoreNum_, coreNum_);
430	
431	    // UB内切分，依次判断各个单轴是否能放下
432	    int64_t blockSingleN = Ops::Base::CeilDiv(cFactor_ * dtypeSizeX_, ONE_BLOCK_SIZE) +
433	                           cFactor_ * Ops::Base::CeilDiv(hwFactor_ * dtypeSizeX_, ONE_BLOCK_SIZE);
434	    int64_t blockSingleC = 1 + Ops::Base::CeilDiv(hwFactor_ * dtypeSizeX_, ONE_BLOCK_SIZE);
435	
436	    int64_t ubBlockVol = ubBlockNum_ / DB_BUFF_NUM;
437	    if (blockSingleC > ubBlockVol) {
438	        ubNFactor_ = 1;
439	        ubCFactor_ = 1;
440	        ubHWFactor_ = (ubBlockVol - 1) * ONE_BLOCK_SIZE / dtypeSizeX_;
441	    } else if (cFactor_ * blockSingleC > ubBlockVol) {
442	        ubNFactor_ = 1;
443	        ubCFactor_ = ubBlockVol / blockSingleC;
444	    } else if (nFactor_ * blockSingleN > ubBlockNum_) {
445	        ubNFactor_ = ubBlockVol / blockSingleN;
446	    }
447	
448	    ubNFactor_ = Min(ubNFactor_, nFactor_);
449	    ubCFactor_ = Min(ubCFactor_, cFactor_);
450	    ubHWFactor_ = Min(ubHWFactor_, hwFactor_);
451	}
452	
453	void ResizeBilinearV2AscendCTilingImpl::DoTilingBroadCastNHWC()
454	{
455	    // HW合轴 N->HW->C依次分核
456	    int64_t lenHW = lenDesH_ * lenDesW_;
457	    if (lenN_ * lenHW <= coreNum_) {
458	        int64_t tileNum = coreNum_ / (lenN_ * lenHW);
459	        nFactor_ = 1;
460	        hwFactor_ = 1;
461	        cFactor_ = Ops::Base::CeilDiv(lenC_, tileNum);
462	        realCoreNum_ = lenN_ * lenHW * Ops::Base::CeilDiv(lenC_, cFactor_);
463	    } else if (lenN_ <= coreNum_) {
464	        int64_t tileNum = coreNum_ / lenN_;
465	        nFactor_ = 1;
466	        hwFactor_ = Ops::Base::CeilDiv(lenHW, tileNum);
467	        realCoreNum_ = lenN_ * Ops::Base::CeilDiv(lenHW, hwFactor_);
468	    } else {
469	        nFactor_ = Ops::Base::CeilDiv(lenN_, coreNum_);
470	        realCoreNum_ = Ops::Base::CeilDiv(lenN_, nFactor_);
471	    }
472	    realCoreNum_ = Min(realCoreNum_, coreNum_);
473	
474	    // UB内切分，依次判断各个单轴是否能放下
475	    int64_t blockSingleN = Ops::Base::CeilDiv(cFactor_ * dtypeSizeX_, ONE_BLOCK_SIZE) +
476	                           hwFactor_ * Ops::Base::CeilDiv(cFactor_ * dtypeSizeX_, ONE_BLOCK_SIZE);
477	    int64_t blockSingleHW = Ops::Base::CeilDiv(cFactor_ * dtypeSizeX_, ONE_BLOCK_SIZE) * DB_BUFF_NUM;
478	
479	    int64_t ubBlockVol = ubBlockNum_ / DB_BUFF_NUM;
480	    if (blockSingleHW > ubBlockVol) {
481	        ubNFactor_ = 1;
482	        ubHWFactor_ = 1;
483	        ubCFactor_ = (ubBlockVol / DB_BUFF_NUM) * ONE_BLOCK_SIZE / dtypeSizeX_;
484	    } else if (hwFactor_ * blockSingleHW > ubBlockVol) {
485	        ubNFactor_ = 1;
486	        ubHWFactor_ = ubBlockVol / blockSingleHW;
487	    } else if (nFactor_ * blockSingleN > ubBlockNum_) {
488	        ubNFactor_ = ubBlockVol / blockSingleN;
489	    }
490	
491	    ubNFactor_ = Min(ubNFactor_, nFactor_);
492	    ubHWFactor_ = Min(ubHWFactor_, hwFactor_);
493	    ubCFactor_ = Min(ubCFactor_, cFactor_);
494	}
495	
496	void ResizeBilinearV2AscendCTilingImpl::DoTilingCParallel()
497	{
498	    int64_t totalLen = lenDesH_ * lenDesW_;
499	
500	    if (totalLen * lenN_ <= coreNum_) {
501	        int64_t tileNum = coreNum_ / (totalLen * lenN_);
502	        hwFactor_ = 1;
503	        nFactor_ = 1;
504	        cFactor_ = Ops::Base::CeilDiv(lenC_, tileNum);
505	        realCoreNum_ = totalLen * lenN_ * Ops::Base::CeilDiv(lenC_, cFactor_);
506	    } else if (totalLen <= coreNum_) {
507	        int64_t tileNum = coreNum_ / totalLen;
508	        hwFactor_ = 1;
509	        nFactor_ = Ops::Base::CeilDiv(lenN_, tileNum);
510	        cFactor_ = lenC_;
511	        realCoreNum_ = totalLen * Ops::Base::CeilDiv(lenN_, nFactor_);
512	    } else {
513	        hwFactor_ = Ops::Base::CeilDiv(totalLen, coreNum_);
514	        nFactor_ = lenN_;
515	        cFactor_ = lenC_;
516	        realCoreNum_ = Ops::Base::CeilDiv(totalLen, hwFactor_);
517	    }
518	
519	    realCoreNum_ = Min(realCoreNum_, coreNum_);
520	
521	    int64_t vol4AxisC = ((ubBlockNum_ / DB_BUFF_NUM) * ONE_BLOCK_SIZE) /
522	                        (C_PARALLEL_X_TENSOR_NUM * dtypeSizeX_ + C_PARALLEL_Y_TENSOR_NUM * dtypeSizeY_);
523	
524	    if (vol4AxisC < lenC_) {
525	        ubNFactor_ = 1;
526	        ubCFactor_ = vol4AxisC;
527	    } else {
528	        ubNFactor_ = vol4AxisC / lenC_;
529	        ubNFactor_ = (ubNFactor_ < nFactor_) ? ubNFactor_ : nFactor_;
530	        ubCFactor_ = lenC_;
531	    }
532	}
533	
534	int64_t ResizeBilinearV2AscendCTilingImpl::FindBest2DTiling(int64_t lenM, int64_t lenN)
535	{
536	    int64_t bestM = 1;
537	    int64_t bestN = coreNum_ / bestM;
538	
539	    int64_t bestDelta = lenM * lenN;
540	    if (bestDelta <= coreNum_) {
541	        return lenM;
542	    }
543	
544	    for (int64_t m = 1; m <= coreNum_; m++) {
545	        int64_t n = coreNum_ / m;
546	
547	        if (m > lenM || n > lenN) {
548	            continue;
549	        }
550	
551	        int64_t mFactor = Ops::Base::CeilDiv(lenM, m);
552	        int64_t nFactor = Ops::Base::CeilDiv(lenN, n);
553	
554	        int64_t delta = mFactor * nFactor;
555	        if (m * n == coreNum_) {
556	            if (lenM % m == 0 && lenN % n == 0) {
557	                delta = 0;
558	            } else if (lenM % m == 0) {
559	                delta = delta - mFactor * (lenN % nFactor);
560	            } else if (lenN % n == 0) {
561	                delta = delta - (lenM % mFactor) * nFactor;
562	            } else {
563	                delta = delta - (lenM % mFactor) * (lenN % nFactor);
564	            }
565	        }
566	
567	        if (delta < bestDelta || (delta == bestDelta && n < bestN)) {
568	            bestM = m;
569	            bestN = n;
570	            bestDelta = delta;
571	        }
572	    }
573	
574	    return bestM;
575	}
