592	void ResizeBilinearV2AscendCTilingImpl::MatchTilingStrategyAndSetTilingKey()
593	{
594	    bool useIdx32 = yShape_.GetShapeSize() < UINT32_MAX && xShape_.GetShapeSize() < UINT32_MAX &&
595	                    lenSrcH_ <= INT32_MAX && lenSrcW_ <= INT32_MAX && lenDesH_ <= INT32_MAX && lenDesW_ <= INT32_MAX;
596	    if (IsMatchAllCopy()) {
597	        tilingKey_ = TILING_KEY_ALL_COPY;
598	    } else if (IsMatchPointCopy()) {
599	        tilingKey_ = TILING_KEY_POINT_COPY;
600	    } else if (IsMatchBroadCastNCHW()) {
601	        tilingKey_ = TILING_KEY_NCHW_BROADCAST;
602	    } else if (IsMatchBroadCastNHWC()) {
603	        tilingKey_ = TILING_KEY_NHWC_BROADCAST;
604	    } else if (IsMatchCParallel()) {
605	        tilingKey_ = TILING_KEY_C_PARALLEL;
606	    } else if (format_ == ge::FORMAT_NCHW) {
607	        int64_t hwSizeThreshold = useIdx32 ? coreNum_ * SIMT_DEFAULT_THREAD_NUM :
608	                                             coreNum_ * SIMT_DEFAULT_THREAD_NUM_IDX64;
609	        bool needHWSplit = xShape_.GetShapeSize() != 1 && (lenSrcW_ != lenDesW_ || lenSrcH_ != lenDesH_) &&
610	                           lenDesH_ * lenDesW_ >= hwSizeThreshold;
611	        if (useIdx32) {
612	            tilingKey_ = (needHWSplit) ? TILING_KEY_SIMT_HW : TILING_KEY_SIMT_NCHW;
613	        } else {
614	            tilingKey_ = (needHWSplit) ? TILING_KEY_SIMT_HW_IDX64 : TILING_KEY_SIMT_NCHW_IDX64;
615	        }
616	    } else if (format_ == ge::FORMAT_NHWC) {
617	        if (useIdx32) {
618	            tilingKey_ = TILING_KEY_SIMT_NHWC;
619	        } else {
620	            tilingKey_ = TILING_KEY_SIMT_NHWC_IDX64;
621	        }
622	    }
623	}
624	
625	void ResizeBilinearV2AscendCTilingImpl::TilingStrategy()
626	{
627	    MatchTilingStrategyAndSetTilingKey();
628	    switch (tilingKey_) {
629	        case TILING_KEY_ALL_COPY: {
630	            DoTilingAllCopy();
631	            break;
632	        }
633	        case TILING_KEY_POINT_COPY: {
634	            DoTilingPointCopy();
635	            break;
636	        }
637	        case TILING_KEY_NCHW_BROADCAST: {
638	            DoTilingBroadCastNCHW();
639	            break;
640	        }
641	        case TILING_KEY_NHWC_BROADCAST: {
642	            DoTilingBroadCastNHWC();
643	            break;
644	        }
645	        case TILING_KEY_C_PARALLEL: {
646	            DoTilingCParallel();
647	            break;
648	        }
649	        case TILING_KEY_SIMT_NHWC:
650	        case TILING_KEY_SIMT_NHWC_IDX64:
651	        case TILING_KEY_SIMT_NCHW:
652	        case TILING_KEY_SIMT_NCHW_IDX64: {
653	            DoTilingSIMT();
654	            break;
655	        }
656	        case TILING_KEY_SIMT_HW:
657	        case TILING_KEY_SIMT_HW_IDX64: {
658	            DoTilingSIMT_HW();
659	            break;
660	        }
661	        default: {
662	            break;
663	        }
664	    }
665	}
