746	ge::graphStatus ResizeBilinearV2AscendCTilingImpl::CheckDtypeAndFormat()
747	{
748	    auto inputXDesc = context_->GetInputDesc(INPUT_X_IDX);
749	    OP_CHECK_NULL_WITH_CONTEXT(context_, inputXDesc);
750	    auto outputYDesc = context_->GetOutputDesc(OUTPUT_Y_IDX);
751	    OP_CHECK_NULL_WITH_CONTEXT(context_, outputYDesc);
752	    dtypeX_ = inputXDesc->GetDataType();
753	    dtypeY_ = outputYDesc->GetDataType();
754	    dtypeSizeX_ = GetSizeByDataType(dtypeX_);
755	    dtypeSizeY_ = GetSizeByDataType(dtypeY_);
756	    if (dtypeSizeX_ <= 0 || dtypeSizeY_ <= 0) {
757	        std::string dtypeMsg = Ops::Base::ToString(dtypeX_) + " and " + Ops::Base::ToString(dtypeY_);
758	        OP_LOGE_FOR_INVALID_DTYPES_WITH_REASON(context_->GetNodeName(), "x and y", dtypeMsg.c_str(),
759	                                               "The dtype sizes of input x and output y must be greater than zero");
760	        return ge::GRAPH_FAILED;
761	    }
762	
763	    format_ = static_cast<ge::Format>(ge::GetPrimaryFormat(inputXDesc->GetStorageFormat()));
764	    auto outFormat = static_cast<ge::Format>(ge::GetPrimaryFormat(outputYDesc->GetStorageFormat()));
765	    if (format_ != outFormat) {
766	        std::string formatMsg = Ops::Base::ToString(format_) + " and " + Ops::Base::ToString(outFormat);
767	        OP_LOGE_FOR_INVALID_FORMATS_WITH_REASON(context_->GetNodeName(), "x and y", formatMsg.c_str(),
768	                                                "The formats of input x and output y must be the same");
769	        return ge::GRAPH_FAILED;
770	    }
771	    OP_CHECK_IF(
772	        (format_ != ge::FORMAT_NCHW && format_ != ge::FORMAT_NHWC),
773	        OP_LOGE_FOR_INVALID_FORMAT(context_->GetNodeName(), "x", Ops::Base::ToString(format_).c_str(), "NCHW or NHWC"),
774	        return ge::GRAPH_FAILED);
775	
776	    return ge::GRAPH_SUCCESS;
777	}
