784	    xShape_ = Ops::Cv::OpTiling::EnsureNotScalar(xStorage->GetStorageShape());
785	    auto yStorage = context_->GetOutputShape(OUTPUT_Y_IDX);
786	    OP_CHECK_NULL_WITH_CONTEXT(context_, yStorage);
787	    yShape_ = Ops::Cv::OpTiling::EnsureNotScalar(yStorage->GetStorageShape());
788	    return ge::GRAPH_SUCCESS;
789	}
790	
791	ge::graphStatus ResizeBilinearV2AscendCTilingImpl::Init(const ResizeBilinearV2CompileInfo* compileInfo)
792	{
793	    OP_LOGD(context_->GetNodeName(), "Enter ResizeBilinearV2AscendCTilingImpl init.");
794	    coreNum_ = compileInfo->core_num;
795	    ubSize_ = compileInfo->ubSize;
796	    OP_CHECK_IF(coreNum_ <= 0 || ubSize_ <= 0, OP_LOGE(context_->GetNodeName(), "coreNum or ubSize is small than zero"),
797	                return ge::GRAPH_FAILED);
798	    ubBlockNum_ = Ops::Base::CeilDiv(ubSize_, ONE_BLOCK_SIZE) - RSV_BLOCK_NUM;
799	    OP_LOGI(context_->GetNodeName(), "coreNum_ is %ld, ubSize_ is %ld, ubBlockNum_ is %ld", coreNum_, ubSize_,
800	            ubBlockNum_);
801	    // Get attrs: alignCorners, halfPixelCenters
802	    auto attrs = context_->GetAttrs();
803	    OP_CHECK_NULL_WITH_CONTEXT(context_, attrs);
804	    const bool* alignCornersPtr = attrs->GetAttrPointer<bool>(ATTR_ALIGN_CORERS_IDX);
805	    OP_CHECK_NULL_WITH_CONTEXT(context_, alignCornersPtr);
806	    const bool* halfPixelCentersPtr = attrs->GetAttrPointer<bool>(ATTR_HALF_PIXEL_CENTERS_IDX);
807	    OP_CHECK_NULL_WITH_CONTEXT(context_, halfPixelCentersPtr);
808	    alignCorners_ = *alignCornersPtr ? 1 : 0;
809	    halfPixelCenters_ = *halfPixelCentersPtr ? 1 : 0;
810	
811	    if (SetScales() != ge::GRAPH_SUCCESS) {
812	        return ge::GRAPH_FAILED;
813	    }
814	
815	    if (CheckDtypeAndFormat() != ge::GRAPH_SUCCESS) {
816	        return ge::GRAPH_FAILED;
817	    }
818	
819	    if (SetShape() != ge::GRAPH_SUCCESS) {
820	        return ge::GRAPH_FAILED;
821	    }
822	
823	    // Check format and dims match or not.
824	    if (CheckFormatMatchDims() != ge::GRAPH_SUCCESS) {
825	        return ge::GRAPH_FAILED;
826	    }
827	
828	    // Set N,C,H,W dim length
829	    SetDimsByFormat();
830	
831	    OP_LOGD(context_->GetNodeName(), "Exit ResizeBilinearV2AscendCTilingImpl init.");
832	    return ge::GRAPH_SUCCESS;
833	}
834	
835	ge::graphStatus ResizeBilinearV2AscendCTilingImpl::DoTiling()
836	{
837	    OP_LOGD(context_->GetNodeName(), "Enter ResizeBilinearV2AscendCTilingImpl DoTiling.v1.1");
838	
839	    TilingStrategy();
840	    FillTilingData();
841	    PrintTilingData();
842	
843	    context_->SetBlockDim(realCoreNum_);
844	    context_->SetTilingKey(tilingKey_);
845	
846	    size_t* workspaces = context_->GetWorkspaceSizes(1);
847	    OP_CHECK_NULL_WITH_CONTEXT(context_, workspaces);
848	    workspaces[0] = WORKSPACE_SIZE;
849	    OP_LOGD(context_->GetNodeName(), "Exit ResizeBilinearV2AscendCTilingImpl DoTiling.");
850	    return ge::GRAPH_SUCCESS;
851	}
852	
853	ge::graphStatus Tiling4ResizeBilinearV2(gert::TilingContext* context)
854	{
855	    OP_LOGD(context->GetNodeName(), "Start Tiling4ResizeBilinearV2.");
856	    auto compileInfo = reinterpret_cast<const ResizeBilinearV2CompileInfo*>(context->GetCompileInfo());
857	    ResizeBilinearV2AscendCTilingImpl tilingImpl = ResizeBilinearV2AscendCTilingImpl(context);
858	    if (tilingImpl.Init(compileInfo) != ge::GRAPH_SUCCESS) {
859	        OP_LOGE(context->GetNodeName(), "Tiling4ResizeBilinearV2 init failed.");
860	        return ge::GRAPH_FAILED;
861	    }
862	
863	    if (tilingImpl.DoTiling() != ge::GRAPH_SUCCESS) {
864	        OP_LOGE(context->GetNodeName(), "Tiling4ResizeBilinearV2 do tiling failed.");
865	        return ge::GRAPH_FAILED;
866	    }
867	    return ge::GRAPH_SUCCESS;
868	}
869	
870	static ge::graphStatus TilingPrepare4ResizeBilinearV2(gert::TilingParseContext* context)
871	{
872	    OP_LOGD(context->GetNodeName(), "Start TilingPrepare4ResizeBilinearV2.");
873	    auto compileInfo = context->GetCompiledInfo<ResizeBilinearV2CompileInfo>();
874	    auto platformInfo = context->GetPlatformInfo();
875	    OP_CHECK_NULL_WITH_CONTEXT(context, platformInfo);
876	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
877	    compileInfo->core_num = ascendcPlatform.GetCoreNumAiv();
878	    OP_CHECK_IF((compileInfo->core_num <= 0), OP_LOGE(context->GetNodeName(), "core num invalid."),
879	                return ge::GRAPH_FAILED);
880	    uint64_t ubSize = 0;
881	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
882	    compileInfo->ubSize = static_cast<int64_t>(ubSize);
883	    OP_CHECK_IF((compileInfo->ubSize <= 0), OP_LOGE(context->GetNodeName(), "ub size invalid."),
884	                return ge::GRAPH_FAILED);
885	
886	    return ge::GRAPH_SUCCESS;
887	}
888	
889	// register tiling interface of the ResizeBilinearV2 op.
890	IMPL_OP_OPTILING(ResizeBilinearV2)
891	    .Tiling(Tiling4ResizeBilinearV2)
892	    .TilingParse<ResizeBilinearV2CompileInfo>(TilingPrepare4ResizeBilinearV2);
893	} // namespace optiling
