11	/*!
12	 * \file resize_bilinear_v2.cpp
13	 * \brief resize_bilinear_v2
14	 */
15	#include "./arch35/resize_bilinear_v2_base.h"
16	#include "./arch35/resize_bilinear_v2_all_copy.h"
17	#include "./arch35/resize_bilinear_v2_point_copy.h"
18	#include "./arch35/resize_bilinear_v2_broadcast_nchw.h"
19	#include "./arch35/resize_bilinear_v2_broadcast_nhwc.h"
20	#include "./arch35/resize_bilinear_v2_c_parallel.h"
21	#include "./arch35/resize_bilinear_v2_nc.h"
22	#include "./arch35/resize_bilinear_v2_simt_nchw.h"
23	#include "./arch35/resize_bilinear_v2_simt_nhwc.h"
24	#include "./arch35/resize_bilinear_v2_simt_nhwc.h"
25	#include "./arch35/resize_bilinear_v2_simt_hw.h"
26	
27	#define TILING_KEY_C_PARALLEL 10000
28	#define TILING_KEY_HW_CACHE 20000
29	#define TILING_KEY_SIMT_NHWC 30000
30	#define TILING_KEY_SIMT_NCHW 30001
31	#define TILING_KEY_SIMT_NHWC_IDX64 30002
32	#define TILING_KEY_SIMT_NCHW_IDX64 30003
33	#define TILING_KEY_SIMT_HW 30004
34	#define TILING_KEY_SIMT_HW_IDX64 30005
35	#define TILING_KEY_ALL_COPY 40000
36	#define TILING_KEY_POINT_COPY 40001
37	#define TILING_KEY_NCHW_BROADCAST 40002
38	#define TILING_KEY_NHWC_BROADCAST 40003
39	
40	using namespace AscendC;
41	
42	extern "C" __global__ __aicore__ void resize_bilinear_v2(GM_ADDR x, GM_ADDR size, GM_ADDR y, GM_ADDR workspace,
43	                                                         GM_ADDR tiling)
44	{
45	    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_AIV_ONLY);
46	    GET_TILING_DATA(tilingData, tiling);
47	
48	    TPipe pipe;
49	
50	    if (TILING_KEY_IS(TILING_KEY_ALL_COPY)) {
51	        ResizeBilinearV2::ResizeBilinearV2AllCopy<DTYPE_X> op;
52	        op.Init(x, size, y, &pipe, &tilingData);
53	        op.Process();
54	        return;
55	    }
56	
57	    if (TILING_KEY_IS(TILING_KEY_POINT_COPY)) {
58	        ResizeBilinearV2::ResizeBilinearV2PointCopy<DTYPE_X> op;
59	        op.Init(x, size, y, &pipe, &tilingData);
60	        op.Process();
61	        return;
62	    }
63	
64	    if (TILING_KEY_IS(TILING_KEY_NCHW_BROADCAST)) {
65	        ResizeBilinearV2::ResizeBilinearV2BroadcastNCHW<DTYPE_X> op;
66	        op.Init(x, size, y, &pipe, &tilingData);
67	        op.Process();
68	        return;
69	    }
70	
71	    if (TILING_KEY_IS(TILING_KEY_NHWC_BROADCAST)) {
72	        ResizeBilinearV2::ResizeBilinearV2BroadcastNHWC<DTYPE_X> op;
73	        op.Init(x, size, y, &pipe, &tilingData);
74	        op.Process();
75	        return;
76	    }
77	    if (TILING_KEY_IS(TILING_KEY_C_PARALLEL)) {
78	        if (tilingData.cFactor < tilingData.lenC) {
79	            ResizeBilinearV2::ResizeBilinearV2Nc<DTYPE_X, DTYPE_Y> op;
80	            op.Init(x, size, y, &pipe, &tilingData);
81	            op.Process();
82	        } else {
83	            ResizeBilinearV2::ResizeBilinearV2CParallel<DTYPE_X, DTYPE_Y> op;
84	            op.Init(x, size, y, &pipe, &tilingData);
85	            op.Process();
86	        }
87	    }
88	
89	    if (TILING_KEY_IS(TILING_KEY_SIMT_NCHW)) {
90	        if (tilingData.halfPixelCenters > 0) {
91	            ResizeBilinearV2::ResizeBilinearV2SimtNCHW<DTYPE_X, DTYPE_Y, true, 0, uint32_t> op;
92	            op.Init(x, size, y, &tilingData);
93	            op.Process();
94	            return;
95	        }
96	        if (tilingData.lenSrcH == tilingData.lenDesH && tilingData.lenSrcW == tilingData.lenDesW) {
97	            ResizeBilinearV2::ResizeBilinearV2SimtNCHW<DTYPE_X, DTYPE_Y, false, 1, uint32_t> op;
98	            op.Init(x, size, y, &tilingData);
99	            op.Process();
100	        } else if (tilingData.lenSrcH == 1 && tilingData.lenSrcW == 1) {
101	            ResizeBilinearV2::ResizeBilinearV2SimtNCHW<DTYPE_X, DTYPE_Y, false, 2, uint32_t> op;
102	            op.Init(x, size, y, &tilingData);
103	            op.Process();
104	        } else if (tilingData.lenDesH == 1 && tilingData.lenDesW == 1) {
105	            ResizeBilinearV2::ResizeBilinearV2SimtNCHW<DTYPE_X, DTYPE_Y, false, 3, uint32_t> op;
106	            op.Init(x, size, y, &tilingData);
107	            op.Process();
108	        } else {
109	            ResizeBilinearV2::ResizeBilinearV2SimtNCHW<DTYPE_X, DTYPE_Y, false, 0, uint32_t> op;
110	            op.Init(x, size, y, &tilingData);
111	            op.Process();
112	        }
113	
114	        return;
115	    }
116	
117	    if (TILING_KEY_IS(TILING_KEY_SIMT_NHWC)) {
118	        if (tilingData.halfPixelCenters > 0) {
119	            ResizeBilinearV2::ResizeBilinearV2SimtNHWC<DTYPE_X, DTYPE_Y, true, 0, uint32_t> op;
120	            op.Init(x, size, y, &tilingData);
121	            op.Process();
122	            return;
123	        }
124	        if (tilingData.lenSrcH == tilingData.lenDesH && tilingData.lenSrcW == tilingData.lenDesW) {
125	            ResizeBilinearV2::ResizeBilinearV2SimtNHWC<DTYPE_X, DTYPE_Y, false, 1, uint32_t> op;
126	            op.Init(x, size, y, &tilingData);
127	            op.Process();
128	        } else if (tilingData.lenSrcH == 1 && tilingData.lenSrcW == 1) {
129	            ResizeBilinearV2::ResizeBilinearV2SimtNHWC<DTYPE_X, DTYPE_Y, false, 2, uint32_t> op;
130	            op.Init(x, size, y, &tilingData);
131	            op.Process();
132	        } else if (tilingData.lenDesH == 1 && tilingData.lenDesW == 1) {
133	            ResizeBilinearV2::ResizeBilinearV2SimtNHWC<DTYPE_X, DTYPE_Y, false, 3, uint32_t> op;
134	            op.Init(x, size, y, &tilingData);
135	            op.Process();
136	        } else {
137	            ResizeBilinearV2::ResizeBilinearV2SimtNHWC<DTYPE_X, DTYPE_Y, false, 0, uint32_t> op;
138	            op.Init(x, size, y, &tilingData);
139	            op.Process();
140	        }
141	        return;
142	    }
143	
144	    if (TILING_KEY_IS(TILING_KEY_SIMT_NCHW_IDX64)) {
145	        if (tilingData.halfPixelCenters > 0) {
146	            ResizeBilinearV2::ResizeBilinearV2SimtNCHW<DTYPE_X, DTYPE_Y, true, 0, uint64_t> op;
147	            op.Init(x, size, y, &tilingData);
148	            op.Process();
149	            return;
150	        }
151	        if (tilingData.lenSrcH == tilingData.lenDesH && tilingData.lenSrcW == tilingData.lenDesW) {
152	            ResizeBilinearV2::ResizeBilinearV2SimtNCHW<DTYPE_X, DTYPE_Y, false, 1, uint64_t> op;
153	            op.Init(x, size, y, &tilingData);
